*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gParamObj = new Array(2);
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.pageSize = 50; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.vScrenID = "ULDSTF30312.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    $c.stf.Combo_CBDataSet(cmb_PerPage);
};
scwin.initPage = function() {
    var ToDay = $c.ut.cGetToday2();
    $c.stf.setObjectValue(edt_EDATE, ToDay);
    var vSDATE = $c.ut.calcMonth(ToDay, -6);
    $c.stf.setObjectValue(edt_SDATE, vSDATE);
};
scwin.fn_openNew = function(row, inAddTyp) {
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    var vNOTI_SVC_ID = '';
    if (inAddTyp == 'Y') {
        vNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
    }
    var url = "";
    url = "/bizspt/ULDSTF30311.gfm?";
    url += "NOTI_SVC_ID=" + vNOTI_SVC_ID;
    url += "&ADD_INPUT=" + inAddTyp;
    url += "&frameID=" + frame.FrameID;
    if (scwin.fn_setParam(vNOTI_SVC_ID, inAddTyp)) {
        // formal arguments
        $c.frame.path("../../").GWinOpen("ULDSTF30311", url, "이메일 신규", 200, 10, 790, 750 + 30, "");
    }
    //frame.CreateFrame("SENDMAIL_NEW", "/bizspt/ULDSTF30311.gfm", "이메일 신규", 200, 10, 790, 750+30, "window",0,0,true);

};
scwin.fn_openDetail = function(row, colid) {
    if (colid == "TITLE") {
        var vNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
        var url = "/bizspt/ULDSTF30313.gfm?";
        url += "NOTI_SVC_ID=" + vNOTI_SVC_ID;
        if (scwin.fn_setParam(vNOTI_SVC_ID)) {
            // formal arguments
            $c.frame.path("../../").GWinOpen("ULDSTF30313", url, "이메일 상세조회", 200, 10, 800, 630 + 40, "");
        }
        //frame.CreateFrame("SENDEMAIL_READ|NOTI_SVC_ID=" + vNOTI_SVC_ID, "/bizspt/ULDSTF30313.gfm", "이메일 상세조회", 200, 10, 790, 630+30, "window",0,0,true);

    } else if (colid == "INPUT") {
        scwin.fn_openNew(row, 'Y');
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.fn_Search = function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return;
    }
    scwin.vCurrPageNo = 0;
    var url = "/NoteMgt.do?method=listSendNote";
    url += "&MDTYPE=1"; // 알림매체타입, 이메일= 1
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    var url = "/NoteMgt.do?method=listSendNote";
    url += "&MDTYPE=1"; // 알림매체타입, 이메일= 1
    url += "&SDATE=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDATE=" + $c.stf.getObjectValue(edt_EDATE);
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.cmb_PerPage_OnSelChange2 = function() {
    var vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
    scwin.pageSize = vPerPage;
    //alert(pageSize);	
    scwin.fn_Search();
};
scwin.cmb_PerPage_OnSelected = function() {

};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    /*
    var vTotalCnt = dts_Grid.NameString(1, "CNT");	
    //FillGridHeader2(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page);		

    //alert(pageNoCnt +", "+getObjectValue(cmb_PerPage)+", "+vTotalCnt);
    //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
    FillGridHeader(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page, 743);		

    */

    if (dts_Grid.errorMsg) {
        $c.win.alert("OnLoadCompleted Error => " + dts_Grid.errorMsg);
    } else {
        if (scwin.pageSize != '0') {
            if (scwin.vCurrPageNo == 0) {
                scwin.vCurrPageNo = 1;
                scwin.totalCnt = dts_Grid.getCellData(0, "CNT");
            }
        } else {
            scwin.totalCnt = rowcount;
        }
        //alert(pageNoCnt +", "+pageSize+", "+totalCnt);
        //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
    }
    $c.cm.CloseWin(scwin.totalCnt, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_openDetail(row, colid);
};
scwin.btn_New_onclick = function() {
    scwin.fn_openNew(0, 'N');
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.initPage();
    scwin.fn_Search();
};
